INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'absorb', 'vt.', '/əbˈzɔːb/', '吸引(注意力);吸收;理解吸收', 'He got so absorbed in the game that he forgot to sleep.', '他玩游戏太入迷,以至于忘了睡觉。', 'Healthy Lifestyle', 1, 0, 'senior', 'wordlist', 'elective3', 'U2', 'be absorbed in', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'abuse', 'n./vt.', '/əˈbjuːs/', '滥用;虐待;辱骂', 'Alcohol abuse can damage both the body and the mind.', '酗酒会损害身体和心理。', 'Healthy Lifestyle', 2, 0, 'senior', 'wordlist', 'elective3', 'U2', 'alcohol abuse', '名词读 /-uːs/,动词读 /-uːz/;美音 /əˈbjuːz/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'alcohol', 'n.', '/ˈælkəhɒl/', '酒;酒精', 'Many young people decide to give up alcohol for a healthier life.', '许多年轻人决定戒酒以获得更健康的生活。', 'Healthy Lifestyle', 3, 0, 'senior', 'wordlist', 'elective3', 'U2', 'give up alcohol', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cigarette', 'n.', '/ˌsɪɡəˈret/', '香烟;卷烟', 'To avoid cigarette smoke is the first step to protect your lungs.', '远离香烟烟雾是保护肺部的第一步。', 'Healthy Lifestyle', 4, 0, 'senior', 'wordlist', 'elective3', 'U2', 'avoid cigarette smoke', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'comedy', 'n.', '/ˈkɒmədi/', '喜剧;喜剧片;滑稽节目', 'When I feel stressed out, I like to watch a comedy to relax.', '当我感到压力大时,我喜欢看喜剧来放松。', 'Healthy Lifestyle', 5, 0, 'senior', 'wordlist', 'elective3', 'U2', 'watch a comedy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'compose', 'vt./vi.', '/kəmˈpəʊz/', '组成;构成;作曲;撰写', 'A healthy lifestyle is composed of good food, exercise and enough sleep.', '健康的生活方式由健康饮食、运动和充足睡眠组成。', 'Healthy Lifestyle', 6, 0, 'senior', 'wordlist', 'elective3', 'U2', 'be composed of', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'consultant', 'n.', '/kənˈsʌltənt/', '顾问;高级顾问医师', 'It is useful to turn to a fitness consultant for advice.', '向健身顾问求助是很有用的。', 'Healthy Lifestyle', 7, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a fitness consultant', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'cue', 'n./vt.', '/kjuː/', '提示;暗示;信号', 'Feeling unhappy can act as a cue to eat unhealthy snacks.', '不开心可以成为吃不健康零食的信号。', 'Healthy Lifestyle', 8, 0, 'senior', 'wordlist', 'elective3', 'U2', 'act as a cue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'delete', 'vt.', '/dɪˈliːt/', '删去;删除', 'There is no delete button that can simply remove a bad habit.', '没有哪个删除键能轻易删掉一个坏习惯。', 'Healthy Lifestyle', 9, 0, 'senior', 'wordlist', 'elective3', 'U2', 'delete some files', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dentist', 'n.', '/ˈdentɪst/', '牙科医生', 'The dentist told me that too much sugar had damaged my teeth.', '牙医告诉我太多糖已经损害了我的牙齿。', 'Healthy Lifestyle', 10, 0, 'senior', 'wordlist', 'elective3', 'U2', 'see a dentist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'discipline', 'n./vt.', '/ˈdɪsəplɪn/', '自制力;纪律;学科;管教', 'To change a bad habit, a person must show some discipline.', '要改掉坏习惯,一个人必须表现出一些自制力。', 'Healthy Lifestyle', 11, 0, 'senior', 'wordlist', 'elective3', 'U2', 'show some discipline', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'disturb', 'vt.', '/dɪˈstɜːb/', '打扰;搅乱;使烦恼', 'It is not polite to disturb your neighbours with loud music at night.', '夜里用很大声的音乐打扰邻居是不礼貌的。', 'Healthy Lifestyle', 12, 0, 'senior', 'wordlist', 'elective3', 'U2', 'disturb the neighbours', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dizzy', 'adj.', '/ˈdɪzi/', '头晕目眩的', 'Skipping breakfast often makes me feel dizzy in class.', '经常不吃早餐让我在课上感到头晕。', 'Healthy Lifestyle', 13, 0, 'senior', 'wordlist', 'elective3', 'U2', 'feel dizzy', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dominate', 'vt./vi.', '/ˈdɒmɪneɪt/', '支配;控制;占有优势', 'It is essential to stop bad habits from dominating a teenager''s life.', '阻止坏习惯支配青少年的生活是至关重要的。', 'Healthy Lifestyle', 14, 0, 'senior', 'wordlist', 'elective3', 'U2', 'dominate one''s life', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'drug', 'n.', '/drʌɡ/', '毒品;药物', 'To take drugs is both illegal and dangerous to your health.', '吸毒既违法又危害你的健康。', 'Healthy Lifestyle', 15, 0, 'senior', 'wordlist', 'elective3', 'U2', 'take drugs', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dynamic', 'adj.', '/daɪˈnæmɪk/', '充满活力的;精力充沛的;动态的', 'After exercising regularly, she felt more dynamic and stronger than ever.', '坚持运动后,她感到比以往更有活力、更强壮。', 'Healthy Lifestyle', 16, 0, 'senior', 'wordlist', 'elective3', 'U2', 'feel dynamic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'enhance', 'vt.', '/ɪnˈhɑːns/', '提高;增强;增进', 'Rock climbing has enhanced the quality of my life.', '攀岩提高了我的生活质量。', 'Healthy Lifestyle', 17, 0, 'senior', 'wordlist', 'elective3', 'U2', 'enhance the quality of life', '美音 /ɪnˈhæns/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'escalator', 'n.', '/ˈeskəleɪtə(r)/', '自动扶梯;滚梯', 'Instead of taking the escalator, you could take the stairs for exercise.', '你可以走楼梯锻炼,而不是坐自动扶梯。', 'Healthy Lifestyle', 18, 0, 'senior', 'wordlist', 'elective3', 'U2', 'take the escalator', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'examine', 'vt.', '/ɪɡˈzæmɪn/', '(仔细)检查;审查;测验', 'We must first examine our bad habit cycles before we can change them.', '我们必须先检视自己的坏习惯循环,然后才能改变它们。', 'Healthy Lifestyle', 19, 0, 'senior', 'wordlist', 'elective3', 'U2', 'examine a habit cycle', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'facilitate', 'vt.', '/fəˈsɪlɪteɪt/', '促进;促使;使便利', 'To facilitate a positive change, we should replace a bad routine with a good one.', '为促成积极的改变,我们应当用好的常规取代坏的常规。', 'Healthy Lifestyle', 20, 0, 'senior', 'wordlist', 'elective3', 'U2', 'facilitate a change', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'flu', 'n.', '/fluː/', '流感', 'Because of his poor diet, he got the flu very easily.', '由于饮食不佳,他很容易得流感。', 'Healthy Lifestyle', 21, 0, 'senior', 'wordlist', 'elective3', 'U2', 'get the flu', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'liberation', 'n.', '/ˌlɪbəˈreɪʃn/', '解放;摆脱', 'Breaking a bad habit gave him a real sense of liberation.', '戒掉一个坏习惯让他有一种真正的解脱感。', 'Healthy Lifestyle', 22, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a sense of liberation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'monthly', 'adv./adj./n.', '/ˈmʌnθli/', '每月(的);每月一次(的);月刊', 'Now my dad and I go rock climbing together monthly.', '现在我和爸爸每月一起去攀岩。', 'Healthy Lifestyle', 23, 0, 'senior', 'wordlist', 'elective3', 'U2', 'go climbing monthly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'negative', 'adj.', '/ˈneɡətɪv/', '消极的;有害的;否定的', 'We could try to replace a negative routine with something more positive.', '我们可以试着用更积极的事情取代消极的常规。', 'Healthy Lifestyle', 24, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a negative routine', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'nut', 'n.', '/nʌt/', '坚果', 'Instead of sweets, she brought fruit and nuts as healthy snacks.', '她没带糖果,而是带了水果和坚果作为健康零食。', 'Healthy Lifestyle', 25, 0, 'senior', 'wordlist', 'elective3', 'U2', 'eat nuts', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pessimistic', 'adj.', '/ˌpesɪˈmɪstɪk/', '悲观的;悲观主义的', 'If we fail at first, we often become pessimistic and give up.', '如果一开始就失败,我们常常变得悲观而放弃。', 'Healthy Lifestyle', 26, 0, 'senior', 'wordlist', 'elective3', 'U2', 'become pessimistic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'physical', 'adj.', '/ˈfɪzɪkl/', '身体的;客观存在的;物理学的', 'Bad habits can lead to physical and mental health problems.', '坏习惯会导致身体和心理健康问题。', 'Healthy Lifestyle', 27, 0, 'senior', 'wordlist', 'elective3', 'U2', 'physical health', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pill', 'n.', '/pɪl/', '药丸;药片', 'There is no magic pill that will change your bad habits for you.', '没有什么神奇药丸能替你改掉坏习惯。', 'Healthy Lifestyle', 28, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a magic pill', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'psychology', 'n.', '/saɪˈkɒlədʒi/', '心理学;心理;心理影响', 'According to modern psychology, we must understand the habit cycle.', '根据现代心理学,我们必须理解习惯循环。', 'Healthy Lifestyle', 29, 0, 'senior', 'wordlist', 'elective3', 'U2', 'modern psychology', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'refresh', 'vt.', '/rɪˈfreʃ/', '使恢复精力;使凉爽;刷新', 'I get refreshed through climbing and feel much more energetic.', '我通过攀岩恢复精力,感觉精神多了。', 'Healthy Lifestyle', 30, 0, 'senior', 'wordlist', 'elective3', 'U2', 'feel refreshed', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'rely', 'vi.', '/rɪˈlaɪ/', '依赖;依靠;信赖', 'The bad habit of relying on unhealthy snacks is easily formed.', '依赖不健康零食的坏习惯很容易养成。', 'Healthy Lifestyle', 31, 0, 'senior', 'wordlist', 'elective3', 'U2', 'rely on', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'repeatedly', 'adv.', '/rɪˈpiːtɪdli/', '重复地;反复地', 'We are what we repeatedly do, so small steps matter.', '我们就是我们反复做的事,所以小步骤很重要。', 'Healthy Lifestyle', 32, 0, 'senior', 'wordlist', 'elective3', 'U2', 'repeatedly take small steps', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'reward', 'n./vt.', '/rɪˈwɔːd/', '回报;奖励;报酬;给以报酬', 'The reward is the good feeling we get from a routine.', '回报是我们从某个常规中得到的好感觉。', 'Healthy Lifestyle', 33, 0, 'senior', 'wordlist', 'elective3', 'U2', 'get a reward', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'shave', 'vi./vt./n.', '/ʃeɪv/', '剃(须发);刮脸', 'It is required for the new soldiers to shave off their beards.', '新兵被要求剃掉胡须。', 'Healthy Lifestyle', 34, 0, 'senior', 'wordlist', 'elective3', 'U2', 'shave off', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'skateboard', 'n./vi.', '/ˈskeɪtbɔːd/', '滑板;滑滑板', 'Sometimes he jumped on his skateboard and rode around the neighbourhood.', '有时他跳上滑板,在小区里到处滑行。', 'Healthy Lifestyle', 35, 0, 'senior', 'wordlist', 'elective3', 'U2', 'ride a skateboard', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'skip', 'vt./vi./n.', '/skɪp/', '跳过;不参加;跳绳;蹦跳', 'It is harmful to skip breakfast often.', '经常不吃早餐是有害的。', 'Healthy Lifestyle', 36, 0, 'senior', 'wordlist', 'elective3', 'U2', 'skip breakfast', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'specialist', 'n.', '/ˈspeʃəlɪst/', '专科医生;专家', 'I persuaded my father to see a lung specialist.', '我说服父亲去看肺科专家。', 'Healthy Lifestyle', 37, 0, 'senior', 'wordlist', 'elective3', 'U2', 'a lung specialist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'stimulate', 'vt.', '/ˈstɪmjuleɪt/', '激发;促进;刺激', 'Do something that stimulates your mind and makes you feel happy.', '做一些能激发你头脑、让你开心的事。', 'Healthy Lifestyle', 38, 0, 'senior', 'wordlist', 'elective3', 'U2', 'stimulate one''s mind', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sugary', 'adj.', '/ˈʃʊɡəri/', '含糖的;甜的', 'She stopped buying all the sweets and sugary drinks.', '她不再买所有的糖果和含糖饮料。', 'Healthy Lifestyle', 39, 0, 'senior', 'wordlist', 'elective3', 'U2', 'sugary drinks', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'surgeon', 'n.', '/ˈsɜːdʒən/', '外科医生', 'It took the surgeon three hours to finish my mother''s lung surgery.', '那位外科医生花了三个小时完成我母亲的肺部手术。', 'Healthy Lifestyle', 40, 0, 'senior', 'wordlist', 'elective3', 'U2', 'an experienced surgeon', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'surgery', 'n.', '/ˈsɜːdʒəri/', '外科手术;外科学', 'If he keeps smoking, he may need surgery in the future.', '如果他继续抽烟,将来可能需要做手术。', 'Healthy Lifestyle', 41, 0, 'senior', 'wordlist', 'elective3', 'U2', 'need surgery', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'tobacco', 'n.', '/təˈbækəʊ/', '烟草;烟叶', 'The nicotine in tobacco can do great damage to your lungs.', '烟草中的尼古丁会严重损害你的肺。', 'Healthy Lifestyle', 42, 0, 'senior', 'wordlist', 'elective3', 'U2', 'tobacco abuse', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'regularly', 'adv.', '/ˈreɡjələli/', '有规律地;定期地;经常地', 'To exercise regularly keeps us fit and healthy.', '有规律地锻炼能使我们保持健康。', 'Healthy Lifestyle', 43, 0, 'senior', 'wordlist', 'elective3', 'U2', 'exercise regularly', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'willpower', 'n.', '/ˈwɪlpaʊə(r)/', '意志力;毅力', 'To give up smoking takes a lot of willpower.', '戒烟需要很大的意志力。', 'Healthy Lifestyle', 44, 0, 'senior', 'wordlist', 'elective3', 'U2', 'take willpower', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u2.01', '①不定式直接作主语,谓语用单数', 'A2', 12, '选择性必修三 U2 — To do sth 直接放句首作主语时,谓语动词用单数(is/keeps/takes…)。如 To exercise regularly keeps us fit. 干扰项 doing/done 等不能与后面的单数谓语自然搭配,过去分词/原形更不能作主语。', 1, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u2.02', '②it 作形式主语,不定式真正主语后置', 'A2', 12, '选择性必修三 U2 — 当不定式作主语较长时,常用 it 作形式主语放句首,把真正的主语(to do)后置:It is + adj. + to do。如 It is important to eat a balanced diet.', 2, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e3u2.03', '③It takes/costs/requires…to do · It is + n. + to do', 'A2', 12, '选择性必修三 U2 — 固定句式:It takes/costs/requires (sb) + 时间/精力/钱 + to do;It is + 名词(a good idea / a pity…) + to do。真正主语都是后置的不定式。如 It takes courage to change.', 3, 'elective3', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ regularly keeps us fit and full of energy.', 'To exercise', 'Exercised', 'Exercise', 'Exercises', 'A', '句首作主语、后接单数谓语 keeps,用不定式 To exercise;过去分词/原形/单数动词都不能作主语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ up smoking takes a great deal of willpower.', 'Given', 'To give', 'Gives', 'Give', 'B', '作主语、谓语 takes 为单数,用不定式 To give up;其余形式不能作主语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ a balanced diet is the key to staying healthy.', 'Eaten', 'Eats', 'To eat', 'Eat', 'C', '句首作主语、谓语 is 单数,用 To eat;过去分词/动词形式不能作主语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ a bad habit early is much easier than changing it later.', 'Recognised', 'Recognises', 'Recognise', 'To recognise', 'D', '作主语、谓语 is,用不定式 To recognise。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ breakfast every morning often makes teenagers feel dizzy.', 'To skip', 'Skipped', 'Skips', 'Skip', 'A', '句首主语、谓语 makes 单数,用 To skip。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ enough sleep helps your body and mind recover.', 'Got', 'To get', 'Gets', 'Get', 'B', '作主语、谓语 helps 单数,用不定式 To get。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ stress in a healthy way takes time and practice.', 'Managed', 'Manages', 'To manage', 'Manage', 'C', '作主语、谓语 takes,用 To manage。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ a negative routine with a positive one really works.', 'Replaced', 'Replaces', 'Replace', 'To replace', 'D', '作主语、谓语 works,用不定式 To replace。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ the stairs instead of the escalator burns more calories.', 'To take', 'Taken', 'Takes', 'Take', 'A', '句首主语、谓语 burns 单数,用 To take。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ your bad habit cycle is the first step to changing it.', 'Examined', 'To examine', 'Examines', 'Examine', 'B', '作主语、谓语 is 单数,用不定式 To examine。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ to a fitness consultant for advice often saves a lot of trouble.', 'Turned', 'Turns', 'To turn', 'Turn', 'C', '作主语、谓语 saves 单数,用 To turn。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ too much sugar damages both your teeth and your health.', 'Eaten', 'Eats', 'Eat', 'To eat', 'D', '作主语、谓语 damages 单数,用不定式 To eat。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ passive cigarette smoke protects your lungs from harm.', 'To avoid', 'Avoided', 'Avoids', 'Avoid', 'A', '句首主语、谓语 protects 单数,用 To avoid。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ a few warm-ups before exercise prevents many injuries.', 'Done', 'To do', 'Does', 'Do', 'B', '作主语、谓语 prevents 单数,用不定式 To do。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ small changes every day makes your lifestyle healthier.', 'Made', 'Makes', 'To make', 'Make', 'C', '作主语、谓语 makes 单数,用 To make。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ junk food too often leads to serious health problems.', 'Eaten', 'Eats', 'Eat', 'To eat', 'D', '作主语、谓语 leads 单数,用不定式 To eat。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ your mind off everything else helps you relax completely.', 'To take', 'Taken', 'Takes', 'Take', 'A', '句首主语、谓语 helps 单数,用 To take。', 2, 17, 'mcq');
