INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ a step-by-step plan works better than changing everything at once.', 'Followed', 'Follows', 'To follow', 'Follow', 'C', '作主语、谓语 works 单数,用 To follow。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.01'), '____ the neighbours with loud music late at night is rather rude.', 'Disturbed', 'Disturbs', 'Disturb', 'To disturb', 'D', '作主语、谓语 is 单数,用不定式 To disturb。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is important ____ a balanced diet if you want to stay healthy.', 'to eat', 'eating', 'eaten', 'that eat', 'A', 'it 作形式主语,真正主语后置用不定式 to eat;动名词不与 it 形式主语搭配,that 从句结构不成立。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is hard ____ a bad habit that has lasted for years.', 'breaking', 'to break', 'broken', 'that break', 'B', 'it 为形式主语,真正主语用 to break。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is necessary ____ what you eat before you go on a diet.', 'checking', 'checked', 'to check', 'that check', 'C', 'it 形式主语 → to check 作真正主语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is useful ____ to a doctor for advice on your health.', 'turning', 'turned', 'that turn', 'to turn', 'D', 'it 形式主语 → to turn 真正主语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is essential ____ harmful habits from controlling your life.', 'to stop', 'stopping', 'stopped', 'that stop', 'A', 'it 形式主语 → to stop 真正主语。', 2, 5, 'mcq');
