INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is dangerous ____ drugs of any kind, even just once.', 'taking', 'taken', 'to take', 'that take', 'C', 'it 形式主语 → to take 真正主语。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is healthy ____ at least thirty minutes every day.', 'exercising', 'exercised', 'that exercise', 'to exercise', 'D', 'it 形式主语 → to exercise 真正主语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is not easy ____ a bad habit quickly, so be patient.', 'to change', 'changing', 'changed', 'that change', 'A', 'it 形式主语 → to change 真正主语。', 2, 9, 'mcq');
