INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is helpful ____ a comedy when you feel stressed out.', 'watching', 'watched', 'to watch', 'that watch', 'C', 'it 形式主语 → to watch 真正主语。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is sensible ____ enough water throughout the day.', 'drinking', 'drunk', 'that drink', 'to drink', 'D', 'it 形式主语 → to drink 真正主语。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.02'), 'It is wrong ____ your neighbours with noise so late at night.', 'to disturb', 'disturbing', 'disturbed', 'that disturb', 'A', 'it 形式主语 → to disturb 真正主语。', 2, 13, 'mcq');
