INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It took the surgeon three hours ____ my mother''s lung surgery.', 'finishing', 'to finish', 'finished', 'that finish', 'B', 'It took sb + 时间 + to do,用 to finish。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a good idea ____ up a new hobby to fight long-term stress.', 'taking', 'taken', 'to take', 'that take', 'C', 'It is + n.(a good idea) + to do,用 to take。', 2, 3, 'mcq');
