INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It costs nothing ____ for a short walk when you feel stressed.', 'going', 'to go', 'gone', 'that go', 'B', 'It costs + n. + to do,用 to go。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a pity ____ such an unhealthy lifestyle at your age.', 'leading', 'led', 'to lead', 'that lead', 'C', 'It is + n.(a pity) + to do,用 to lead。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It takes patience ____ a bad habit over a period of time.', 'breaking', 'broken', 'that break', 'to break', 'D', 'It takes + n. + to do,用 to break。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a wise choice ____ sugary drinks with plain water.', 'to replace', 'replacing', 'replaced', 'that replace', 'A', 'It is + n.(a wise choice) + to do,用 to replace。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It requires effort ____ your habit cycle and then adapt it.', 'examining', 'to examine', 'examined', 'that examine', 'B', 'It requires + n. + to do,用 to examine。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It takes only a minute ____ the stairs instead of the escalator.', 'climbing', 'climbed', 'to climb', 'that climb', 'C', 'It takes + 时间 + to do,用 to climb。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a relief ____ free from the stress of exams at last.', 'feeling', 'felt', 'that feel', 'to feel', 'D', 'It is + n.(a relief) + to do,用 to feel。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It takes courage ____ no to junk food when everyone is eating it.', 'to say', 'saying', 'said', 'that say', 'A', 'It takes + n. + to do,用 to say。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It costs a lot of money ____ surgery, so it is better to stay healthy.', 'having', 'to have', 'had', 'that have', 'B', 'It costs + n. + to do,用 to have。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a good habit ____ regularly and sleep early every night.', 'exercising', 'exercised', 'to exercise', 'that exercise', 'C', 'It is + n.(a good habit) + to do,用 to exercise。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It requires time ____ a new healthy routine until it feels natural.', 'forming', 'formed', 'that form', 'to form', 'D', 'It requires + n. + to do,用 to form。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It takes self-control ____ away from your phone before bed.', 'to stay', 'staying', 'stayed', 'that stay', 'A', 'It takes + n. + to do,用 to stay。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a smart move ____ snacks from home instead of buying sweets.', 'bringing', 'to bring', 'brought', 'that bring', 'B', 'It is + n.(a smart move) + to do,用 to bring。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It costs you nothing ____ a comedy and have a good laugh.', 'watching', 'watched', 'to watch', 'that watch', 'C', 'It costs + n. + to do,用 to watch。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective3' AND unit='U2' AND code='e3u2.03'), 'It is a real pleasure ____ healthy and full of energy again.', 'being', 'been', 'that be', 'to be', 'D', 'It is + n.(a real pleasure) + to do,用 to be。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'How Habits Are Formed', 'As teenagers grow up, they become more independent and start making their own decisions. During this period, it can be easy for some of them to form bad habits. According to modern psychology, every habit follows a simple cycle with three parts. First comes the cue, an action, event or situation that acts as a signal to do something. Next comes the routine, the regular action you take in response to the cue. Last comes the reward, the good feeling you get from the routine. For example, when we feel unhappy, that feeling is the cue; we eat unhealthy snacks as the routine; and the pleasure we get is the reward. Because the reward feels good, we are much more likely to repeat the whole cycle, and soon the bad habit is firmly formed. The good news is that once we understand how this cycle works, we can change it. By keeping the same cue but choosing a more positive routine, we are able to turn a bad habit into a good one.', '说明·习惯循环', 173, '[{"q":"Why is it easy for some teenagers to form bad habits?","answer":"A","options":["Because they grow more independent and make their own choices.","Because they are forced by their parents.","Because they have no free time at all.","Because they never feel unhappy."],"explanation":"开头 ''they become more independent and start making their own decisions'' 的转述。"},{"q":"What is the correct order of the habit cycle?","answer":"B","options":["Reward, routine, then cue.","Cue, routine, then reward.","Routine, reward, then cue.","Reward, cue, then routine."],"explanation":"原文依次讲 cue → routine → reward。"},{"q":"How can someone turn a bad habit into a good one?","answer":"A","options":["By keeping the cue but choosing a better routine.","By avoiding all cues forever.","By repeating the same routine more often.","By giving up the reward completely."],"explanation":"末句 ''keeping the same cue but choosing a more positive routine'' 的转述。"}]'::jsonb, '[{"word":"cue","cn":"提示;信号"},{"word":"routine","cn":"常规;惯常做法"},{"word":"reward","cn":"回报;好处"},{"word":"psychology","cn":"心理学"}]'::jsonb, 2, 'elective3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'There Is No Magic Pill', 'Many of us try to change a bad habit quickly. We promise ourselves that from tomorrow everything will be different. But when we are not successful straight away, we often become pessimistic and give up after only a few attempts. In fact, the most successful way to change is not suddenly, but slowly over a period of time. As the Chinese philosopher Laozi wrote, a journey of a thousand miles begins with a single step. One small step may seem to mean nothing, yet it is truly essential. To reach the goal of change, a person must show some discipline and repeatedly take many tiny steps in the right direction. For young people there is plenty of time, so there is no need to rush. However, you should also know the truth: there is no magic pill and no delete button that will remove a bad habit for you. You have to think carefully about your own habits and decide on the changes you want. In the end, the power to build a healthy and happy life lies in your own hands.', '议论·戒坏习惯靠坚持', 182, '[{"q":"Why do many people give up changing a bad habit?","answer":"B","options":["Because they have no bad habits.","Because they grow discouraged when quick results do not appear.","Because they succeed too easily.","Because their friends stop them."],"explanation":"原文 ''not successful straight away… become pessimistic and give up'' 的转述。"},{"q":"What does the writer say is the best way to change?","answer":"C","options":["Suddenly, all in one day.","By taking a special pill.","Slowly, through many small steps over time.","By waiting until you are an adult."],"explanation":"原文 ''not suddenly, but slowly over a period of time… many tiny steps'' 的转述。"},{"q":"What does the writer mean by saying there is no magic pill?","answer":"D","options":["You should buy more medicine.","Pills are bad for your health.","Doctors cannot help anyone.","No quick or easy tool can change a habit for you."],"explanation":"原文 ''no magic pill… you have to think… decide on the changes'' 的转述。"}]'::jsonb, '[{"word":"pessimistic","cn":"悲观的"},{"word":"discipline","cn":"自制力"},{"word":"repeatedly","cn":"反复地"},{"word":"essential","cn":"至关重要的"}]'::jsonb, 2, 'elective3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Managing Everyday Stress', 'It is not easy to manage stress successfully, and yet stress is something almost every student faces. When you are stressed, even a small problem can suddenly seem much worse than it really is. Serious stress can also lead to health issues such as dizziness, skin conditions and breathing problems, so it is best to find a solution as soon as you can. For minor stress, simple actions often work well. You might wash your face with cold water or go for a short walk outside to clear your mind. To fight long-term stress, it is a great idea to take up a new hobby that you truly enjoy. Ride a skateboard, go bowling or watch a comedy: whatever stimulates your mind and makes you feel happy. The key is to choose something that completely takes your mind off everything else. If you can concentrate fully on one pleasant activity for a while, you will almost certainly feel much more refreshed afterwards. So next time you feel worn out, remember to free yourself by finding something positive to focus on.', '说明·压力管理', 180, '[{"q":"What can serious stress lead to, according to the text?","answer":"A","options":["Health problems such as dizziness and breathing trouble.","More free time.","Better marks at school.","A stronger body."],"explanation":"原文 ''lead to health issues such as dizziness, skin conditions and breathing problems'' 的转述。"},{"q":"What does the writer suggest for minor stress?","answer":"B","options":["Taking some pills.","Simple actions like a cold-water wash or a short walk.","Sleeping all day.","Ignoring it completely."],"explanation":"原文 ''wash your face with cold water or go for a short walk'' 的转述。"},{"q":"Why does taking up a hobby help with long-term stress?","answer":"C","options":["It costs a lot of money.","It makes you feel more tired.","It lets your mind fully escape from your worries.","It keeps you thinking about the problem."],"explanation":"原文 ''completely takes your mind off everything else… feel much more refreshed'' 的转述。"}]'::jsonb, '[{"word":"stimulate","cn":"激发;刺激"},{"word":"refresh","cn":"使恢复精力"},{"word":"dizziness","cn":"头晕"},{"word":"worn out","cn":"筋疲力尽的"}]'::jsonb, 2, 'elective3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Wang Lu Gives Up Sugar', 'Before attending a summer camp about health, Wang Lu hardly ever felt well, either in body or in mind. He often felt sleepy and dizzy, and he lacked passion for anything. Worst of all, he caught the flu easily and suffered from many toothaches. At the camp he heard a powerful line: change the world by changing yourself. This stimulated him. A dentist had once examined him and warned that too much sugar in his meals had damaged both his teeth and his health. So Wang Lu made up his mind to change two things: to eat nothing with added sugar and to exercise regularly. He stopped buying the sweets, biscuits and sugary drinks he used to have every day. Whenever he went out with friends, he brought snacks from home instead, such as fruit, nuts and dried meat. His exercise plan was simple: he went outside for at least thirty minutes daily to do something active. After a while the results were fantastic. He felt more dynamic and stronger than before, slept soundly at night, and no longer suffered from the flu or toothaches.', '记叙·健康饮食改变', 185, '[{"q":"How did Wang Lu feel before the camp?","answer":"D","options":["Happy and full of passion.","Healthy and strong.","Calm and well rested.","Unwell, sleepy and lacking energy."],"explanation":"原文 ''hardly ever felt well… sleepy and dizzy, and he lacked passion'' 的转述。"},{"q":"What two changes did Wang Lu decide to make?","answer":"A","options":["To cut out added sugar completely and to work out regularly.","To sleep more and study less.","To take medicine and stay indoors.","To buy more sweets and biscuits."],"explanation":"原文 ''to eat nothing with added sugar and to exercise regularly'' 的转述。"},{"q":"What were the results of his new lifestyle?","answer":"B","options":["He felt even more tired than before.","He grew stronger, slept well and stopped getting ill.","He started getting the flu more often.","He gave up after a week."],"explanation":"原文 ''more dynamic and stronger… slept soundly… no longer suffered from the flu'' 的转述。"}]'::jsonb, '[{"word":"dentist","cn":"牙医"},{"word":"sugary","cn":"含糖的"},{"word":"dynamic","cn":"充满活力的"},{"word":"examine","cn":"检查"}]'::jsonb, 2, 'elective3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Climbing Towards a Better Life', 'When George started high school, he often felt stressed out, and he always relaxed by playing computer games. Soon he got so absorbed that he played day and night. Playing was fun at the time, but afterwards he felt even more worn out than before. After joining a summer camp about personal life choices, he realised it was very important to adjust his lifestyle, so he decided to take control. It was a big struggle not to join his friends online, because he was mad for those games. However, he understood that to succeed in quitting, he had to replace gaming with something else. He thought of rock climbing, bowling, watching comedies and playing basketball. In the end he chose climbing, and now he and his dad go rock climbing together every month. This new habit has enhanced the quality of his life by improving his health and increasing his happiness. He gets refreshed through climbing, spends more time with his father, and keeps meeting new friends. After six months, he feels far more energetic and believes he can truly change himself for the better.', '记叙·用运动取代坏习惯', 185, '[{"q":"How did George usually relax when he felt stressed?","answer":"C","options":["By going for a walk.","By reading books.","By playing computer games for hours.","By calling his dad."],"explanation":"原文 ''relaxed by playing computer games… day and night'' 的转述。"},{"q":"Why did George decide he had to replace gaming?","answer":"D","options":["Because his parents took away his phone.","Because games were too expensive.","Because his friends moved away.","Because simply stopping was not enough to quit successfully."],"explanation":"原文 ''to succeed in quitting, he had to replace gaming with something else'' 的转述。"},{"q":"What has rock climbing done for George?","answer":"A","options":["It has improved his health and made him happier.","It has made him more tired and lonely.","It has had no effect on his life.","It has kept him away from his father."],"explanation":"原文 ''enhanced the quality of his life by improving his health and increasing his happiness'' 的转述。"}]'::jsonb, '[{"word":"absorb","cn":"吸引(全部注意力)"},{"word":"enhance","cn":"提高;增强"},{"word":"worn out","cn":"筋疲力尽的"},{"word":"monthly","cn":"每月一次的"}]'::jsonb, 2, 'elective3', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Putting Down the Phone', 'For many students today, using a phone too much has quietly become a bad habit. The cue often appears the moment you feel bored or stressed: almost without thinking, you pick up your phone. The routine of scrolling for video after video gives a small reward, a quick feeling of fun, so the cycle repeats again and again. The trouble is that hours can disappear this way, and you may end up feeling worn out rather than relaxed. Worse still, late-night screen time disturbs your sleep and leaves you tired and dizzy the next day. To break this habit, you do not need to throw your phone away. Instead, examine your own habit cycle and gently change the routine. When boredom acts as the cue, you might read a few pages of a book, take a short walk, or chat with a friend face to face. It takes a little discipline at first, but each small choice makes the next one easier. Step by step, you can take back control of your time and feel more refreshed and focused every day.', '议论·手机成瘾与对策', 181, '[{"q":"What usually acts as the cue for picking up the phone?","answer":"B","options":["Finishing your homework.","Feeling bored or stressed.","Eating a healthy meal.","Going to sleep early."],"explanation":"原文 ''the moment you feel bored or stressed… you pick up your phone'' 的转述。"},{"q":"What problem does late-night phone use cause?","answer":"C","options":["It improves your sleep.","It makes you feel refreshed.","It damages your rest and makes you feel exhausted the following morning.","It has no effect at all."],"explanation":"原文 ''late-night screen time disturbs your sleep and leaves you tired and dizzy'' 的转述。"},{"q":"What does the writer advise instead of throwing the phone away?","answer":"D","options":["Buying a newer phone.","Using the phone even more.","Never going outside again.","Examining the habit cycle and replacing the routine."],"explanation":"原文 ''examine your own habit cycle and gently change the routine'' 的转述。"}]'::jsonb, '[{"word":"disturb","cn":"搅乱;打扰"},{"word":"examine","cn":"检视;检查"},{"word":"discipline","cn":"自制力"},{"word":"refresh","cn":"使恢复精力"}]'::jsonb, 2, 'elective3', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U2', 'Going to Bed Earlier', 'Last term I had a really bad (1)____: I stayed up late every night watching short videos on my phone. As a result, I often felt (2)____ in class and could not concentrate. My teacher told me that getting enough sleep is the (3)____ to staying healthy. So I decided to (4)____ this habit step by step. First, I worked out my own habit cycle. The (5)____ was feeling bored at night, and my routine was to pick up my phone. To (6)____ a positive change, I put my phone in another room before bed and read a book instead. It was not easy at first, and it took some (7)____ to keep going. But slowly my new routine started to feel (8)____. Now I sleep soundly and wake up feeling (9)____. I no longer feel dizzy in the morning, and my marks have improved too. This small change has truly (10)____ the quality of my daily life.', 158, 2, '[{"q":"1","answer":"A","options":["habit","price","garden","ticket"],"explanation":"a bad habit 坏习惯。"},{"q":"2","answer":"B","options":["proud","sleepy","rich","polite"],"explanation":"felt sleepy 感到困倦。"},{"q":"3","answer":"C","options":["price","noise","key","shop"],"explanation":"the key to 关键。"},{"q":"4","answer":"D","options":["build","form","keep","change"],"explanation":"change this habit 改掉这个习惯。"},{"q":"5","answer":"A","options":["cue","reward","routine","result"],"explanation":"the cue 提示/信号。"},{"q":"6","answer":"B","options":["stop","facilitate","break","lose"],"explanation":"facilitate a change 促成改变。"},{"q":"7","answer":"C","options":["money","water","discipline","sugar"],"explanation":"some discipline 一些自制力。"},{"q":"8","answer":"D","options":["strange","painful","boring","natural"],"explanation":"feel natural 感觉自然。"},{"q":"9","answer":"A","options":["refreshed","tired","worried","angry"],"explanation":"feeling refreshed 精神饱满。"},{"q":"10","answer":"B","options":["lowered","enhanced","ruined","ignored"],"explanation":"enhanced the quality 提升了质量。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U2', 'Cutting Down on Coffee', 'My sister used to (1)____ on coffee to get through every busy day. She drank five or six cups, and by evening she felt (2)____ out and could not sleep. A doctor warned her that too much caffeine was not (3)____ for her health. So she made up her (4)____ to cut down slowly. She knew that to stop suddenly would only make her (5)____, so she removed one cup each week. Whenever she felt the (6)____ to grab a coffee, she chose to drink water or take a short (7)____ outside instead. This new routine gave her a small (8)____: she felt calmer and more relaxed. After a month, she was down to one cup a day and slept much (9)____ at night. She told me that the hardest part was simply the first week. Now she feels far more (10)____ and full of energy, and she is proud of the change she has made.', 156, 2, '[{"q":"1","answer":"C","options":["carry","look","rely","wait"],"explanation":"rely on 依赖。"},{"q":"2","answer":"D","options":["proud","rich","calm","worn"],"explanation":"worn out 筋疲力尽。"},{"q":"3","answer":"A","options":["good","loud","late","empty"],"explanation":"not good for health 对健康不好。"},{"q":"4","answer":"B","options":["hand","mind","foot","head"],"explanation":"make up one''s mind 下定决心。"},{"q":"5","answer":"C","options":["happy","polite","pessimistic","quiet"],"explanation":"make her pessimistic 让她悲观。"},{"q":"6","answer":"D","options":["price","noise","shop","cue"],"explanation":"the cue 信号/冲动。"},{"q":"7","answer":"A","options":["walk","sleep","meal","exam"],"explanation":"take a short walk 散步。"},{"q":"8","answer":"B","options":["price","reward","noise","error"],"explanation":"a small reward 小回报。"},{"q":"9","answer":"C","options":["worse","louder","better","later"],"explanation":"slept much better 睡得好多了。"},{"q":"10","answer":"D","options":["tired","bored","afraid","dynamic"],"explanation":"more dynamic 更有活力。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U2', 'Learning to Cook Healthy Meals', 'When I first lived away from home, I ate junk food every day because it was (1)____ and quick. Soon I started to feel (2)____ and caught the flu easily. I realised that to eat a (3)____ diet was something I had to learn. So I decided to (4)____ how to cook simple, healthy meals. At first my dishes tasted (5)____, and I almost wanted to give up. But I kept (6)____ a few new recipes each week. Slowly my cooking improved, and I began to (7)____ how good fresh food could taste. I replaced sugary drinks with water and added more vegetables and (8)____ to my plate. The (9)____ were clear: I had more energy, slept better, and rarely got sick. Cooking for myself also saved a lot of (10)____. Now I am sure that a few small choices in the kitchen can really change the way you feel every day.', 152, 2, '[{"q":"1","answer":"A","options":["cheap","loud","polite","ancient"],"explanation":"cheap 便宜的。"},{"q":"2","answer":"B","options":["proud","weak","rich","calm"],"explanation":"feel weak 感到虚弱。"},{"q":"3","answer":"C","options":["noisy","lazy","balanced","empty"],"explanation":"a balanced diet 均衡饮食。"},{"q":"4","answer":"D","options":["forget","waste","hide","learn"],"explanation":"learn how to cook 学会做饭。"},{"q":"5","answer":"A","options":["terrible","lovely","sweet","fresh"],"explanation":"tasted terrible 味道糟糕。"},{"q":"6","answer":"B","options":["selling","trying","losing","breaking"],"explanation":"kept trying 不断尝试。"},{"q":"7","answer":"C","options":["forget","doubt","appreciate","waste"],"explanation":"appreciate 欣赏/体会到。"},{"q":"8","answer":"D","options":["sweets","sugar","salt","nuts"],"explanation":"vegetables and nuts 蔬菜和坚果。"},{"q":"9","answer":"A","options":["results","prices","noises","tickets"],"explanation":"the results 结果。"},{"q":"10","answer":"B","options":["trouble","money","sleep","stress"],"explanation":"saved a lot of money 省了很多钱。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U2', 'Laughter Is Good Medicine', 'Many people do not know that laughter can be a natural (1)____ for our health. When we laugh, our body relaxes and our mind feels (2)____. Research shows that a few minutes of real laughter can (3)____ the blood vessels and ease pain, just as gentle exercise does. Laughter is also said to be (4)____, which means that when one person laughs, others nearby often start to laugh too. After a stressful day, watching a (5)____ with friends is a simple way to feel better. It (6)____ your mind and helps you forget your worries for a while. Of course, laughter alone cannot (7)____ every problem, but it certainly helps. Doctors agree that people who laugh often tend to feel more (8)____ and stay healthier. So the next time you feel worn out or (9)____, try to find something funny. A good laugh costs nothing, yet it can truly (10)____ the quality of your day.', 155, 2, '[{"q":"1","answer":"C","options":["price","machine","medicine","garden"],"explanation":"natural medicine 天然良药。"},{"q":"2","answer":"D","options":["angry","rich","late","calm"],"explanation":"feel calm 感到平静。"},{"q":"3","answer":"A","options":["open","close","break","sell"],"explanation":"open the blood vessels 舒张血管。"},{"q":"4","answer":"B","options":["empty","contagious","quiet","lazy"],"explanation":"contagious 有感染力的(会传染笑声)。"},{"q":"5","answer":"C","options":["price","machine","comedy","ticket"],"explanation":"watch a comedy 看喜剧。"},{"q":"6","answer":"D","options":["loses","breaks","sells","refreshes"],"explanation":"refreshes your mind 让头脑恢复。"},{"q":"7","answer":"A","options":["solve","enjoy","buy","open"],"explanation":"solve every problem 解决每个问题。"},{"q":"8","answer":"B","options":["bored","positive","afraid","tired"],"explanation":"feel more positive 更积极。"},{"q":"9","answer":"C","options":["polite","ancient","stressed","rich"],"explanation":"worn out or stressed 疲惫或有压力。"},{"q":"10","answer":"D","options":["ruin","lower","waste","enhance"],"explanation":"enhance the quality 提升质量。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U2', 'My First Month of Running', 'I used to spend my free time sitting and (1)____ snacks in front of the screen. After a check-up, the doctor said I needed to (2)____ regularly, or my health would get worse. So I made up my mind to (3)____ a running habit. The first week was a real (4)____, and my legs ached every morning. There were days when I felt (5)____ and wanted to quit. But I reminded myself that change happens (6)____, one small step at a time. Instead of running far, I just ran for ten minutes and slowly added more. To keep myself going, I gave myself a small (7)____ after each run, such as a nice bath. Little by little, running became part of my (8)____ life. Now I feel far more (9)____ than before, and I sleep soundly every night. The biggest lesson I learned is that you do not need a magic (10)____ to change your life; you just need patience and a single small step.', 165, 2, '[{"q":"1","answer":"A","options":["eating","selling","hiding","throwing"],"explanation":"eating snacks 吃零食。"},{"q":"2","answer":"B","options":["sleep","exercise","shout","travel"],"explanation":"exercise regularly 规律锻炼。"},{"q":"3","answer":"C","options":["break","lose","form","stop"],"explanation":"form a habit 养成习惯。"},{"q":"4","answer":"D","options":["holiday","joke","game","struggle"],"explanation":"a real struggle 真正的艰难。"},{"q":"5","answer":"A","options":["pessimistic","proud","polite","rich"],"explanation":"felt pessimistic 感到悲观。"},{"q":"6","answer":"B","options":["suddenly","slowly","loudly","never"],"explanation":"happens slowly 慢慢发生。"},{"q":"7","answer":"C","options":["price","noise","reward","error"],"explanation":"a small reward 小奖励。"},{"q":"8","answer":"D","options":["empty","lazy","boring","daily"],"explanation":"daily life 日常生活。"},{"q":"9","answer":"A","options":["energetic","tired","bored","afraid"],"explanation":"more energetic 更有精力。"},{"q":"10","answer":"B","options":["shop","pill","city","garden"],"explanation":"a magic pill 神奇药丸。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective3', 'U2', 'A Balanced Daily Routine', 'A healthy lifestyle is really about finding the right (1)____ and making good choices. Our life is composed of many parts, such as study, family, friends and rest. If one part comes to (2)____ everything else, the others are ignored and we lose our balance. That is why it is important to (3)____ your daily activities carefully. Your health depends on what you (4)____ to do each day. Neither too much nor too (5)____ of anything is good for you. For example, studying all night may seem hard-working, but it will leave you (6)____ and unable to focus. A wiser plan is to (7)____ small, healthy changes step by step. Sleep early, eat well, and make time to (8)____ your body every day. Try to replace a (9)____ routine, like endless scrolling, with something more positive. Over time, these little choices add up, and your whole lifestyle becomes (10)____. Remember, you do not have to change everything at once.', 159, 2, '[{"q":"1","answer":"C","options":["price","noise","balance","ticket"],"explanation":"the right balance 恰当的平衡。"},{"q":"2","answer":"D","options":["sell","open","break","dominate"],"explanation":"dominate everything 支配一切。"},{"q":"3","answer":"A","options":["examine","forget","waste","lose"],"explanation":"examine your activities 检视你的活动。"},{"q":"4","answer":"B","options":["sell","choose","hide","throw"],"explanation":"what you choose to do 你选择做的事。"},{"q":"5","answer":"C","options":["loud","rich","little","polite"],"explanation":"too little 太少。"},{"q":"6","answer":"D","options":["proud","calm","happy","worn"],"explanation":"worn out 筋疲力尽。"},{"q":"7","answer":"A","options":["make","forget","lose","sell"],"explanation":"make small changes 做小改变。"},{"q":"8","answer":"B","options":["sell","move","break","lose"],"explanation":"move your body 活动身体。"},{"q":"9","answer":"C","options":["happy","polite","negative","ancient"],"explanation":"a negative routine 消极的常规。"},{"q":"10","answer":"D","options":["worse","louder","emptier","healthier"],"explanation":"becomes healthier 变得更健康。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·对话 A Visit to the Doctor', '选择性必修三 U2 · dialogue', 3, 'Patient: Hello, doctor. I want to lose weight, but I just can''t seem to do it.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·短文 The Habit Cycle', '选择性必修三 U2 · passage', 2, 'Modern psychology tells us that every habit follows a simple cycle. First there is a cue, a signal that makes you want to do something. Then there is a routine, the action you take after the cue. Finally there is a reward, the good feeling you get. Because the reward feels nice, you repeat the cycle again and again. To change a bad habit, keep the same cue but choose a more positive routine.', '现代心理学告诉我们,每个习惯都遵循一个简单的循环:先是提示(让你想做某事的信号),然后是常规(提示后采取的行动),最后是回报(你得到的好感觉)。因为回报让人舒服,你会反复重复这个循环。要改掉坏习惯,就保留同样的提示,但换一个更积极的常规。', 'uk_female', '[{"q":"What is the first part of the habit cycle?","type":"choice","answer":"D","options":["The reward.","The routine.","The result.","The cue."]},{"q":"What is the routine?","type":"choice","answer":"A","options":["The action you take after the cue.","The signal to start.","The good feeling you get.","The end of the habit."]},{"q":"Why do people repeat the cycle?","type":"choice","answer":"B","options":["Because the cue is loud.","Because the reward feels good.","Because the routine is boring.","Because they are forced to."]},{"q":"According to the passage, where does the habit cycle come from?","type":"choice","answer":"C","options":["Old stories.","A magic pill.","Modern psychology.","A dentist."]},{"q":"How can you change a bad habit?","type":"choice","answer":"D","options":["Remove the cue forever.","Repeat the same routine more.","Give up the reward entirely.","Keep the cue but choose a better routine."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U2');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·对话 Too Much Phone Time', '选择性必修三 U2 · dialogue', 3, 'Lily: You look tired again, Tom. Not enough sleep, right?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·短文 Snacks from Home', '选择性必修三 U2 · passage', 2, 'After a dentist warned her about too much sugar, Mei changed the way she ate. She stopped buying sweets, biscuits and sugary drinks. Whenever she went out with friends, she brought snacks from home instead, such as fruit, nuts and dried meat. She also drank plain water rather than soft drinks. After a few weeks, her teeth felt better and she had more energy. She says that to eat well is now a simple part of her daily life.', '牙医警告美糖吃太多后,她改变了饮食方式:不再买糖果、饼干和含糖饮料;和朋友出门时改带家里的零食,如水果、坚果和肉干;还用白水代替软饮料。几周后,她的牙齿好转、精力更充沛。她说现在健康饮食已是她日常生活中简单的一部分。', 'uk_female', '[{"q":"Who warned Mei about sugar?","type":"choice","answer":"B","options":["A teacher.","A dentist.","Her friend.","A coach."]},{"q":"What did Mei stop buying?","type":"choice","answer":"C","options":["Fruit and nuts.","Water and tea.","Sweets, biscuits and sugary drinks.","Dried meat."]},{"q":"What did she bring from home instead?","type":"choice","answer":"D","options":["Soft drinks.","Cakes and sweets.","Nothing at all.","Fruit, nuts and dried meat."]},{"q":"What did she drink instead of soft drinks?","type":"choice","answer":"A","options":["Plain water.","Coffee.","Sugary juice.","Hot chocolate."]},{"q":"How does Mei feel about healthy eating now?","type":"choice","answer":"B","options":["It is too hard to keep up.","It is a simple part of her daily life.","It is boring and useless.","It made her health worse."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U2');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·对话 Advice on Breaking a Habit', '选择性必修三 U2 · dialogue', 3, 'Sam: I really need to stop drinking so much cola, but I just can''t.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·短文 Beating Stress', '选择性必修三 U2 · passage', 2, 'It is not easy to manage stress, but a few simple steps really help. For minor stress, wash your face with cold water or go for a short walk outside. For long-term stress, take up a hobby that you truly enjoy, such as bowling or watching a comedy. The key is to choose something that takes your mind off your worries. If you can focus on one pleasant activity for a while, you will feel much more refreshed afterwards.', '管理压力并不容易,但几个简单步骤真的有用:轻微压力时,用冷水洗脸或到外面短暂散步;长期压力时,培养一个你真正喜欢的爱好,比如打保龄球或看喜剧;关键是选一件能让你忘掉烦恼的事;如果能专注于一件愉快的活动一会儿,之后你会感觉精神好多了。', 'uk_female', '[{"q":"What does the passage suggest for minor stress?","type":"choice","answer":"D","options":["Taking strong medicine.","Sleeping for the whole day.","Eating lots of sweets.","A cold-water wash or a short walk."]},{"q":"What is suggested for long-term stress?","type":"choice","answer":"A","options":["Taking up a hobby you enjoy.","Working even harder.","Avoiding all people.","Drinking more coffee."]},{"q":"What kind of activity should you choose?","type":"choice","answer":"B","options":["One that costs a lot of money.","One that takes your mind off your worries.","One that makes you more worried.","One that keeps you thinking about stress."]},{"q":"What examples of hobbies are given?","type":"choice","answer":"C","options":["Studying and cleaning.","Shopping and cooking.","Bowling and watching a comedy.","Sleeping and reading."]},{"q":"How will you feel after focusing on a pleasant activity?","type":"choice","answer":"D","options":["More tired than before.","Angry and bored.","Exactly the same.","Much more refreshed."]}]'::jsonb, '[]'::jsonb, 'short', 'elective3', 'U2');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Advice on a Healthy Lifestyle / How to Quit a Bad Habit(给同学的健康生活建议信)', 'A Letter of Advice on Quitting a Bad Habit', '假设你叫李华,你的英国朋友 Chris 在信中说自己沉迷手机、常常熬夜,身体越来越差,向你求助。请用英语写一封约100词的回信,内容包括:① 表示理解并简要分析这个坏习惯的危害;② 用「习惯循环」给出一两条切实可行的改变方法;③ 鼓励他相信小步骤、坚持下去。注意用上本单元的不定式作主语句型(如 To exercise regularly keeps us fit. / It is important to … / It takes willpower to …)。', 'Suppose you are Li Hua. Your British friend Chris has written to say that he is addicted to his phone, often stays up late and feels less and less healthy. Write a reply (about 100 words) including: 1) understanding and a brief note on why the habit is harmful; 2) one or two practical ways to change, using the idea of the habit cycle; 3) some encouragement to keep going step by step. Try to use the infinitive-as-subject patterns from this unit.', '["理解并点出危害(I know how you feel … Using a phone too much can harm your sleep and health.)","用习惯循环给方法(To break this habit, keep the cue but change the routine …)","用本单元不定式句型(To exercise regularly keeps us fit. / It takes willpower to …)","鼓励坚持小步骤(Don''t give up — small steps over time really work.)"]'::jsonb, 70, 100, 'Dear Chris,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective3', 'U2', '{"title":"不定式作主语(The Infinitive as the Subject)速查","intro":"不定式 to do 可以作句子的主语。直接作主语时谓语用单数;当主语较长时,常用 it 作形式主语放句首,把真正的主语(to do)后置。判断口诀:句首要的是「主语」且是「做某事」→ 用 to do,谓语跟单数。","table":{"headers":["句型","结构 / 例句"],"rows":[["不定式直接作主语","To do sth + 单数谓语:To exercise regularly keeps us fit."],["it 作形式主语","It is + adj. + to do:It is important to eat a balanced diet."],["It takes/costs/requires","It takes/costs/requires (sb) + 时间/精力/钱 + to do:It takes courage to change."],["It is + 名词 + to do","It is a good idea to relax. / It is a pity to give up."]]},"specialRules":[{"rule":"不定式直接作主语时,谓语动词永远用单数","mark":"To give up smoking takes(不是 take)willpower."},{"rule":"主语太长时用 it 作形式主语,真正主语 to do 后置,it 本身无意义","mark":"It is hard to break a bad habit.(= To break a bad habit is hard.)"},{"rule":"It takes/costs/requires + (sb) + 时间/精力/钱 + to do 是固定句式","mark":"It took the surgeon three hours to finish the surgery."},{"rule":"句首作主语只能用 to do 或 doing,不能用过去分词或动词原形/单三形式","mark":"To eat √ / Eaten × / Eat × / Eats ×"}],"why":["不定式 to do 表示一个具体、有时偏将来或一次性的动作,放句首就充当主语;由于它在语义上是单个动作单元,所以谓语跟单数。主语过长会让句子头重脚轻,于是把 it 放前面当形式主语,真正的 to do 放后面,读起来更顺。"],"gaokaoPoints":["不定式作主语 vs it 形式主语:句首是否需要后置——长主语用 it … to do 是高考语法填空与写作高频。","谓语单复数:不定式作主语谓语用单数(keeps/is/takes),常设错项考动词形式。","It takes/costs/requires sb time/money to do 固定句式,真正主语恒为 to do。"],"examVsReal":[{"exam":"To eat a balanced diet is important.（书面/考试,不定式直接作主语)","real":"It''s important to eat a balanced diet.","note":"口语和真实英语里更常用 it 作形式主语,把长主语后置;考试两种都对,但写作避免头重脚轻。"},{"exam":"To change a habit takes time.（考试常用不定式主语)","real":"Changing a habit takes time.","note":"真实英语里谈泛指、习惯性动作时常用动名词作主语;本单元考点聚焦不定式作主语。"}]}'::jsonb);
